const VECTORS: &[Vector] = &[V0, V1, V2, V3, V4, V5, V6, V7];

/// Every newly supported type must parse with the exact expected stats, and the visitor
/// must see every log (exhaustive traversal, never filtered traversal).
#[test]
fn real_vectors_parse_with_expected_stats() {
    let mut seen_types = std::collections::BTreeSet::new();
    for v in VECTORS {
        let mut visited = 0u64;
        let stats = visit_logs(v.encoded, |_success, _log| {
            visited += 1;
            Ok(())
        })
        .unwrap_or_else(|e| {
            panic!(
                "block {} idx {} type {:#04x} failed: {:?}",
                v.block, v.index, v.envelope, e
            )
        });
        assert_eq!(
            stats.envelope_type,
            Some(v.envelope),
            "envelope type mismatch block {} idx {}",
            v.block, v.index
        );
        assert_eq!(
            stats.success,
            v.success,
            "success mismatch block {} idx {}",
            v.block, v.index
        );
        assert_eq!(
            stats.cumulative_gas_used,
            v.cumulative_gas_used,
            "cumulative gas mismatch block {} idx {}",
            v.block, v.index
        );
        assert_eq!(
            stats.log_count,
            v.log_count,
            "log count mismatch block {} idx {}",
            v.block, v.index
        );
        assert_eq!(
            visited,
            v.log_count,
            "visitor did not see every log block {} idx {}",
            v.block, v.index
        );
        seen_types.insert(v.envelope);
    }
    for t in [0x04u8, 0x64, 0x68, 0x69, 0x6a] {
        assert!(seen_types.contains(&t), "missing coverage for newly supported type {:#04x}", t);
    }
}

/// A failing callback must propagate, not be swallowed by the new type arms.
#[test]
fn callback_error_propagates_for_new_types() {
    for v in VECTORS.iter().filter(|v| v.log_count > 0) {
        let err = visit_logs(v.encoded, |_s, _l| Err(kai_volume_chunk::Error::Receipt("boom")));
        assert!(err.is_err(), "callback error must propagate for type {:#04x}", v.envelope);
    }
}

/// Malformed input: truncation and trailing bytes must still be rejected under the newly
/// accepted type bytes. Widening the type set must not weaken structural checks.
#[test]
fn malformed_new_type_envelopes_still_rejected() {
    for v in VECTORS {
        let cut = &v.encoded[..v.encoded.len() - 1];
        assert!(
            visit_logs(cut, |_, _| Ok(())).is_err(),
            "truncated receipt accepted for type {:#04x} block {} idx {}",
            v.envelope, v.block, v.index
        );
        assert!(
            visit_logs(&v.encoded[..1], |_, _| Ok(())).is_err(),
            "type byte alone accepted for type {:#04x}",
            v.envelope
        );
        let mut extra = v.encoded.to_vec();
        extra.push(0x80);
        assert!(
            visit_logs(&extra, |_, _| Ok(())).is_err(),
            "trailing bytes accepted for type {:#04x} block {} idx {}",
            v.envelope, v.block, v.index
        );
    }
}

/// Types we did NOT add must remain rejected. Guards against wildcard acceptance.
#[test]
fn unsupported_type_bytes_still_rejected() {
    let base: &[u8] = &VECTORS[0].encoded;
    for bad in [0x00u8, 0x03, 0x05, 0x63, 0x65, 0x66, 0x67, 0x6b, 0x7f] {
        let mut v = base.to_vec();
        v[0] = bad;
        assert!(
            visit_logs(&v, |_, _| Ok(())).is_err(),
            "type byte {:#04x} must remain unsupported",
            bad
        );
    }
}

/// Full acceptance-set sweep over 0x00..=0xff. Pins the exact three-way classification:
/// - 0xc0..=0xff  -> accepted as LEGACY (envelope_type None), payload is the whole slice
/// - the seven typed bytes -> accepted as TYPED (envelope_type Some(byte))
/// - every other byte -> rejected
/// A future widening, or an accidental wildcard, fails this test.
#[test]
fn full_byte_sweep_pins_exact_acceptance_set() {
    // Valid four-field payload, taken from a real typed receipt minus its type byte.
    let body: Vec<u8> = VECTORS[0].encoded[1..].to_vec();
    let accepted: [u8; 7] = [0x01, 0x02, 0x04, 0x64, 0x68, 0x69, 0x6a];

    let mut n_legacy = 0usize;
    let mut n_typed = 0usize;
    let mut n_rejected = 0usize;

    for b in 0x00u32..=0xffu32 {
        let b = b as u8;
        let is_legacy_range = (0xc0..=0xff).contains(&b);
        // For the legacy range the whole candidate must itself be the RLP list,
        // so pass `body` directly. Otherwise prefix the candidate with the type byte.
        let candidate: Vec<u8> = if is_legacy_range {
            body.clone()
        } else {
            let mut v = vec![b];
            v.extend_from_slice(&body);
            v
        };

        let result = visit_logs(&candidate, |_, _| Ok(()));

        if is_legacy_range {
            let st = result.unwrap_or_else(|e| panic!("legacy byte {:#04x} must parse, got {:?}", b, e));
            assert_eq!(st.envelope_type, None, "legacy byte {:#04x} must report no envelope type", b);
            n_legacy += 1;
        } else if accepted.contains(&b) {
            let st = result.unwrap_or_else(|e| panic!("typed byte {:#04x} must parse, got {:?}", b, e));
            assert_eq!(st.envelope_type, Some(b), "typed byte {:#04x} must report its own envelope type", b);
            n_typed += 1;
        } else {
            assert!(
                result.is_err(),
                "byte {:#04x} must be rejected, but it parsed successfully",
                b
            );
            n_rejected += 1;
        }
    }

    assert_eq!(n_typed, 7, "exactly seven typed bytes must be accepted");
    assert_eq!(n_legacy, 64, "0xc0..=0xff is 64 legacy bytes");
    assert_eq!(n_rejected, 256 - 64 - 7, "all remaining bytes must be rejected");
}
